-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): linesizing capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- BEGINNER
--   Fields read with the switch on: imo1_friction_factor,
--   imo1_friction_drop_psi, imo1_total_drop_psi.
--   The Studio card rounds f to 4 decimals and the drops to 1 against tolerances
--   of 1e-9 and 1e-5.
--   APPENDED: Read the figures in the Pipeline & Line Sizing Studio with its
--   Full precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- INTERMEDIATE
--   Fields read with the switch on: brass_outlet_pressure_psia.
--   The gas card rounds the outlet pressure to 1 decimal against a tolerance of
--   1e-5.
--   APPENDED: Read the figures in the Pipeline & Line Sizing Studio with its
--   Full precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/linesizing.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- linesizing / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'linesizing' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w3 linesizing refused: linesizing/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '71127bf8bb282d316eece66e821418c8' and fields = '[{"key": "imo1_velocity_fts", "tol": 0.000001, "unit": "ft/s", "label": "Velocity in the IMO-1 line", "expected": 2.2025394846583723}, {"key": "imo1_reynolds", "tol": 0.01, "unit": "dimensionless", "label": "Reynolds number of the IMO-1 line", "expected": 20628.885999489932}, {"key": "imo1_friction_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Darcy friction factor", "expected": 0.027758986529736098}, {"key": "imo1_friction_drop_psi", "tol": 0.00001, "unit": "psi", "label": "Friction loss along the line", "expected": 29.776303763560268}, {"key": "imo1_total_drop_psi", "tol": 0.00001, "unit": "psi", "label": "Total pressure loss", "expected": 95.25672115819587}, {"key": "imo1_erosional_velocity_fts", "tol": 0.000001, "unit": "ft/s", "label": "Erosional velocity at the agreed c factor", "expected": 16.593209696456945}]'::jsonb then 'old'
              when md5(prompt) = 'df78475afeda4dea9dfde8bcda6bdc9e' and fields = '[{"key": "imo1_velocity_fts", "tol": 0.000001, "unit": "ft/s", "label": "Velocity in the IMO-1 line", "expected": 2.2025394846583723}, {"key": "imo1_reynolds", "tol": 0.01, "unit": "dimensionless", "label": "Reynolds number of the IMO-1 line", "expected": 20628.885999489932}, {"key": "imo1_friction_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Darcy friction factor", "expected": 0.027758986529736098}, {"key": "imo1_friction_drop_psi", "tol": 0.00001, "unit": "psi", "label": "Friction loss along the line", "expected": 29.776303763560268}, {"key": "imo1_total_drop_psi", "tol": 0.00001, "unit": "psi", "label": "Total pressure loss", "expected": 95.25672115819587}, {"key": "imo1_erosional_velocity_fts", "tol": 0.000001, "unit": "ft/s", "label": "Erosional velocity at the agreed c factor", "expected": 16.593209696456945}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'linesizing' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w3 linesizing refused: linesizing/beginner matches neither its post-W1 form (prompt md5 71127bf8bb282d316eece66e821418c8) nor its W3 form (prompt md5 df78475afeda4dea9dfde8bcda6bdc9e), with the fields this file was generated against';
  end if;

  -- linesizing / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'linesizing' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 linesizing refused: linesizing/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '527c62f2061e1280b395909e62d82715' and fields = '[{"key": "brass_elevation_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Elevation factor, e to the s", "expected": 0.9537503233579996}, {"key": "brass_weymouth_scfd", "tol": 1000, "unit": "scfd", "label": "Weymouth rate", "expected": 121983243.41355602}, {"key": "brass_panhandleb_scfd", "tol": 1000, "unit": "scfd", "label": "Panhandle B rate", "expected": 158089257.28536567}, {"key": "brass_general_scfd", "tol": 1000, "unit": "scfd", "label": "General Flow rate", "expected": 135290712.75490567}, {"key": "brass_general_friction_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Darcy friction factor the General Flow solve settles on", "expected": 0.010546475636391016}, {"key": "brass_outlet_pressure_psia", "tol": 0.00001, "unit": "psia", "label": "Outlet pressure at the contracted rate", "expected": 999.6232577666815}]'::jsonb then 'old'
              when md5(prompt) = '361443b5b019418f1699f6642a8f6045' and fields = '[{"key": "brass_elevation_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Elevation factor, e to the s", "expected": 0.9537503233579996}, {"key": "brass_weymouth_scfd", "tol": 1000, "unit": "scfd", "label": "Weymouth rate", "expected": 121983243.41355602}, {"key": "brass_panhandleb_scfd", "tol": 1000, "unit": "scfd", "label": "Panhandle B rate", "expected": 158089257.28536567}, {"key": "brass_general_scfd", "tol": 1000, "unit": "scfd", "label": "General Flow rate", "expected": 135290712.75490567}, {"key": "brass_general_friction_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Darcy friction factor the General Flow solve settles on", "expected": 0.010546475636391016}, {"key": "brass_outlet_pressure_psia", "tol": 0.00001, "unit": "psia", "label": "Outlet pressure at the contracted rate", "expected": 999.6232577666815}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'linesizing' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w3 linesizing refused: linesizing/intermediate matches neither its post-W1 form (prompt md5 527c62f2061e1280b395909e62d82715) nor its W3 form (prompt md5 361443b5b019418f1699f6642a8f6045), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w3 linesizing: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 linesizing refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'IMO-1 is the crude transfer line from the IMO flow station to the tank farm. It carries 6800 barrels a day of dead crude at a density of 52.3 lb/ft3 and a viscosity of 4.2 centipoise, downstream of separation, so take the rate at line conditions. The line is 6.065 inches bore and 19800 feet long, and it climbs 180 feet from the station to the farm. It has been in service for years, so use an absolute roughness of 0.006 inches rather than new steel. The isometric adds up to a resistance coefficient sum of 3.85 velocity heads for all its bends, valves and the exit into the tank. The operator has agreed a site erosional c factor of 120 for this service, which is its own figure and not one of the published rows. Work the chain the studio works: the bore to a flow area, the area and the rate to a velocity, the velocity to a Reynolds number, the Reynolds number and the relative roughness to a friction factor, and then the three losses kept apart. Report: the velocity in ft/s; the Reynolds number; the Darcy friction factor; the friction loss in psi; the total pressure loss in psi; and the erosional velocity in ft/s at the agreed c factor. Read the figures in the Pipeline & Line Sizing Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'linesizing' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 linesizing refused: linesizing/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'df78475afeda4dea9dfde8bcda6bdc9e' and fields = '[{"key": "imo1_velocity_fts", "tol": 0.000001, "unit": "ft/s", "label": "Velocity in the IMO-1 line", "expected": 2.2025394846583723}, {"key": "imo1_reynolds", "tol": 0.01, "unit": "dimensionless", "label": "Reynolds number of the IMO-1 line", "expected": 20628.885999489932}, {"key": "imo1_friction_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Darcy friction factor", "expected": 0.027758986529736098}, {"key": "imo1_friction_drop_psi", "tol": 0.00001, "unit": "psi", "label": "Friction loss along the line", "expected": 29.776303763560268}, {"key": "imo1_total_drop_psi", "tol": 0.00001, "unit": "psi", "label": "Total pressure loss", "expected": 95.25672115819587}, {"key": "imo1_erosional_velocity_fts", "tol": 0.000001, "unit": "ft/s", "label": "Erosional velocity at the agreed c factor", "expected": 16.593209696456945}]'::jsonb) from public.academy_capstones where app_slug = 'linesizing' and tier = 'beginner' and active) is not true then
    raise exception 'w3 linesizing refused: linesizing/beginner does not read back as its W3 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'The BRASS trunk carries gas from the BRASS gathering station down to the terminal. It is 15 inches bore and 58 miles long, it runs at 1150 psia at the station and 840 psia at the terminal, and the terminal sits 950 feet BELOW the station, so the elevation change is a descent. The gas has a gravity of 0.62, the average flowing temperature along the line is 552 degrees Rankine and the average compressibility is 0.845. The line has been surveyed and its transmission efficiency is 0.92, which is a stated condition of this line and not a figure to be looked up. Where the General Flow equation is asked for, use a gas viscosity of 0.0125 centipoise and a pipe roughness of 0.0006 inches. First work the elevation group that all four published forms share, then run the forms themselves, and then turn the question round: the terminal has contracted for 92000000 standard cubic feet a day, and you are asked what pressure it will actually see at that rate through the Weymouth form. Report: the elevation factor e to the s; the Weymouth rate in scfd; the Panhandle B rate in scfd; the General Flow rate in scfd; the Darcy friction factor the General Flow solve settles on; and the outlet pressure in psia at the contracted rate. Read the figures in the Pipeline & Line Sizing Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'linesizing' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 linesizing refused: linesizing/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '361443b5b019418f1699f6642a8f6045' and fields = '[{"key": "brass_elevation_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Elevation factor, e to the s", "expected": 0.9537503233579996}, {"key": "brass_weymouth_scfd", "tol": 1000, "unit": "scfd", "label": "Weymouth rate", "expected": 121983243.41355602}, {"key": "brass_panhandleb_scfd", "tol": 1000, "unit": "scfd", "label": "Panhandle B rate", "expected": 158089257.28536567}, {"key": "brass_general_scfd", "tol": 1000, "unit": "scfd", "label": "General Flow rate", "expected": 135290712.75490567}, {"key": "brass_general_friction_factor", "tol": 1E-9, "unit": "dimensionless", "label": "Darcy friction factor the General Flow solve settles on", "expected": 0.010546475636391016}, {"key": "brass_outlet_pressure_psia", "tol": 0.00001, "unit": "psia", "label": "Outlet pressure at the contracted rate", "expected": 999.6232577666815}]'::jsonb) from public.academy_capstones where app_slug = 'linesizing' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 linesizing refused: linesizing/intermediate does not read back as its W3 form';
  end if;

  raise notice 'w3 linesizing: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
